from pathlib import Path

PAGE = Path("pages/7_Manual_Planning_with_Interests.py")

if not PAGE.exists():
    raise SystemExit("Run this from the PTMC-Rostering repository root.")

text = PAGE.read_text()

IMPORT_ANCHOR = 'from roster_engine.manual_planning_repository import ManualPlanningRepository\n'
IMPORT_REPLACEMENT = 'from roster_engine.manual_planning_repository import ManualPlanningRepository\nfrom roster_engine.fc_manual_continuity import (\n    availability_conflict_dates,\n    build_fc_segment_payloads,\n    capacity_conflict_dates,\n    group_fc_segments,\n    is_active_fc_requirement,\n    uncovered_fc_dates,\n)\n'
TABS_OLD = 'duty_tab, cover_tab, interest_tab, review_tab = st.tabs(\n    ["Manual duties", "Manual covers", "PTMC Overnight Interest", "Review planning inputs"]\n)\n'
TABS_NEW = 'duty_tab, cover_tab, fc_tab, interest_tab, review_tab = st.tabs(\n    [\n        "Manual duties",\n        "Manual covers",\n        "FC continuity",\n        "PTMC Overnight Interest",\n        "Review planning inputs",\n    ]\n)\n'
MODE_OLD = '            assignment_mode = st.radio(\n                "Assignment", ["Active cover", "FC reserve"], horizontal=True\n            )\n'
MODE_NEW = '            selected_is_active_fc = (\n                is_active_fc_requirement(\n                    selected_requirement\n                )\n            )\n\n            assignment_options = (\n                ["FC reserve"]\n                if selected_is_active_fc\n                else ["Active cover"]\n            )\n\n            assignment_mode = st.radio(\n                "Assignment",\n                assignment_options,\n                horizontal=True,\n            )\n\n            if selected_is_active_fc:\n                st.info(\n                    "Active FC is planned in the FC continuity tab so a medic "\n                    "can be locked for the whole deployment or a defined "\n                    "handover segment."\n                )\n'
FC_TAB_CODE = '\nwith fc_tab:\n    st.subheader("FC continuity planner")\n    st.caption(\n        "An FC assignment is treated as a continuous deployment. "\n        "Whole FC is the default; use a custom segment for handovers."\n    )\n\n    fc_requirements = [\n        requirement\n        for requirement in cover_requirements\n        if is_active_fc_requirement(requirement)\n    ]\n\n    if not fc_requirements:\n        st.info("No active FC requirements exist for this month.")\n    elif not cover_fit_names:\n        st.warning("No active Cover Fit personnel are available.")\n    else:\n        fc_requirement_by_id = {\n            requirement.id: requirement\n            for requirement in fc_requirements\n        }\n\n        fc_requirement_id = st.selectbox(\n            "FC requirement",\n            options=list(fc_requirement_by_id),\n            format_func=lambda requirement_id: (\n                f"{fc_requirement_by_id[requirement_id].requesting_unit} — "\n                f"{fc_requirement_by_id[requirement_id].cover_type} "\n                f"({fc_requirement_by_id[requirement_id].start_date:%d %b} "\n                f"→ {fc_requirement_by_id[requirement_id].end_date:%d %b})"\n            ),\n            key="fc_continuity_requirement",\n        )\n\n        fc_requirement = fc_requirement_by_id[fc_requirement_id]\n\n        existing_fc_segments = group_fc_segments(\n            requirement_id=fc_requirement.id,\n            assignments=manual_assignments,\n        )\n\n        uncovered_dates = uncovered_fc_dates(\n            requirement=fc_requirement,\n            assignments=manual_assignments,\n        )\n\n        if existing_fc_segments:\n            st.markdown("#### Current manual FC plan")\n\n            st.dataframe(\n                [\n                    {\n                        "Segment": index + 1,\n                        "Personnel": segment.person_name,\n                        "From": segment.start_date,\n                        "Until": segment.end_date,\n                        "Days": segment.day_count,\n                        "Override": segment.allow_override,\n                        "Remarks": segment.remarks or "",\n                    }\n                    for index, segment in enumerate(existing_fc_segments)\n                ],\n                use_container_width=True,\n                hide_index=True,\n                column_config={\n                    "From": st.column_config.DateColumn(\n                        "From",\n                        format="DD MMM",\n                    ),\n                    "Until": st.column_config.DateColumn(\n                        "Until",\n                        format="DD MMM",\n                    ),\n                },\n            )\n\n            segment_index = st.selectbox(\n                "Segment to remove",\n                options=list(range(len(existing_fc_segments))),\n                format_func=lambda index: (\n                    f"{existing_fc_segments[index].person_name}: "\n                    f"{existing_fc_segments[index].start_date:%d %b} "\n                    f"→ {existing_fc_segments[index].end_date:%d %b}"\n                ),\n                key=f"fc_segment_delete_selector_{fc_requirement.id}",\n            )\n\n            if st.button(\n                "Delete selected FC segment",\n                key=f"delete_fc_segment_{fc_requirement.id}",\n                use_container_width=True,\n            ):\n                segment = existing_fc_segments[segment_index]\n\n                try:\n                    for assignment_id in segment.assignment_ids:\n                        (\n                            get_supabase()\n                            .table("roster_manual_assignments")\n                            .delete()\n                            .eq("id", assignment_id)\n                            .execute()\n                        )\n                except Exception as exc:\n                    st.error(f"Unable to delete FC segment: {exc}")\n                else:\n                    clear_manual_cache()\n                    st.success("FC segment deleted.")\n                    st.rerun()\n\n        if uncovered_dates:\n            st.warning(\n                f"Manual FC plan still has {len(uncovered_dates)} uncovered "\n                "day(s). The generator may fill them using FC continuity."\n            )\n        else:\n            st.success("The full FC requirement is manually covered.")\n\n        st.divider()\n        st.markdown("#### Add FC segment")\n\n        segment_mode = st.radio(\n            "Duration",\n            ["Whole FC", "Custom segment"],\n            horizontal=True,\n            key=f"fc_segment_mode_{fc_requirement.id}",\n        )\n\n        if segment_mode == "Whole FC":\n            fc_start = fc_requirement.start_date\n            fc_end = fc_requirement.end_date\n            st.caption(f"{fc_start:%d %b %Y} → {fc_end:%d %b %Y}")\n        else:\n            c1, c2 = st.columns(2)\n\n            with c1:\n                fc_start = st.date_input(\n                    "Cover from",\n                    value=fc_requirement.start_date,\n                    min_value=fc_requirement.start_date,\n                    max_value=fc_requirement.end_date,\n                    format="DD/MM/YYYY",\n                    key=f"fc_segment_start_{fc_requirement.id}",\n                )\n\n            with c2:\n                fc_end = st.date_input(\n                    "Cover until",\n                    value=fc_requirement.end_date,\n                    min_value=fc_start,\n                    max_value=fc_requirement.end_date,\n                    format="DD/MM/YYYY",\n                    key=(\n                        f"fc_segment_end_{fc_requirement.id}_"\n                        f"{fc_start.isoformat()}"\n                    ),\n                )\n\n        fc_person_options = [\n            name\n            for name in personnel_available_on(\n                person_by_name,\n                fc_start,\n                cover_fit_only=True,\n            )\n            if (\n                person_by_name[name].person.leaving_date is None\n                or person_by_name[name].person.leaving_date > fc_end\n            )\n        ]\n\n        fc_person = st.selectbox(\n            "Cover Fit personnel",\n            options=fc_person_options,\n            key=(\n                f"fc_segment_person_{fc_requirement.id}_"\n                f"{fc_start.isoformat()}_{fc_end.isoformat()}"\n            ),\n            disabled=not fc_person_options,\n        )\n\n        conflict_dates = (\n            availability_conflict_dates(\n                person_name=fc_person,\n                start_date=fc_start,\n                end_date=fc_end,\n                availability_entries=availability_rows,\n            )\n            if fc_person\n            else []\n        )\n\n        capacity_dates = capacity_conflict_dates(\n            requirement=fc_requirement,\n            start_date=fc_start,\n            end_date=fc_end,\n            assignments=manual_assignments,\n        )\n\n        if conflict_dates:\n            st.warning(\n                f"{fc_person} has Availability plotted on "\n                f"{len(conflict_dates)} selected day(s): "\n                + ", ".join(\n                    current_date.strftime("%d %b")\n                    for current_date in conflict_dates\n                )\n            )\n\n        if capacity_dates:\n            st.error(\n                "The FC requirement is already fully manually assigned on: "\n                + ", ".join(\n                    current_date.strftime("%d %b")\n                    for current_date in capacity_dates\n                )\n            )\n\n        fc_override = st.checkbox(\n            "Allow manual override for Availability conflicts",\n            value=False,\n            key=(\n                f"fc_segment_override_{fc_requirement.id}_"\n                f"{fc_start.isoformat()}_{fc_end.isoformat()}"\n            ),\n        )\n\n        fc_remarks = st.text_input(\n            "Remarks",\n            placeholder="Optional handover / FC note",\n            key=f"fc_segment_remarks_{fc_requirement.id}",\n        )\n\n        if st.button(\n            "Lock FC segment",\n            type="primary",\n            use_container_width=True,\n            key=(\n                f"lock_fc_segment_{fc_requirement.id}_"\n                f"{fc_start.isoformat()}_{fc_end.isoformat()}"\n            ),\n            disabled=(\n                not fc_person_options\n                or bool(capacity_dates)\n                or (bool(conflict_dates) and not fc_override)\n            ),\n        ):\n            payloads = build_fc_segment_payloads(\n                roster_month_id=roster_month_id,\n                requirement=fc_requirement,\n                person_name=fc_person,\n                start_date=fc_start,\n                end_date=fc_end,\n                allow_override=fc_override,\n                remarks=fc_remarks,\n            )\n\n            try:\n                (\n                    get_supabase()\n                    .table("roster_manual_assignments")\n                    .insert(payloads)\n                    .execute()\n                )\n            except Exception as exc:\n                st.error(f"Unable to lock FC segment: {exc}")\n            else:\n                clear_manual_cache()\n                st.success(\n                    f"FC segment locked: {fc_person}, "\n                    f"{fc_start:%d %b} → {fc_end:%d %b}."\n                )\n                st.rerun()\n\n'

if "from roster_engine.fc_manual_continuity import" not in text:
    if IMPORT_ANCHOR not in text:
        raise SystemExit("Could not find ManualPlanningRepository import.")
    text = text.replace(IMPORT_ANCHOR, IMPORT_REPLACEMENT, 1)

if TABS_OLD in text:
    text = text.replace(TABS_OLD, TABS_NEW, 1)
elif "duty_tab, cover_tab, fc_tab, interest_tab, review_tab" not in text:
    raise SystemExit("Could not find Manual Planning tabs.")

if MODE_OLD in text:
    text = text.replace(MODE_OLD, MODE_NEW, 1)
elif "selected_is_active_fc" not in text:
    raise SystemExit("Could not find cover assignment mode control.")

if "with fc_tab:" not in text:
    marker = "with interest_tab:\n"
    if marker not in text:
        raise SystemExit("Could not find PTMC Overnight Interest tab.")
    text = text.replace(marker, FC_TAB_CODE + marker, 1)

compile(text, str(PAGE), "exec")

backup = PAGE.with_suffix(".py.step22_backup")
if not backup.exists():
    backup.write_text(PAGE.read_text())

PAGE.write_text(text)

print("Step 22 applied successfully.")
print("FC continuity planner added to Manual Planning.")
